.nt-color-dot.color-pink { background: #fecdd3; }
.nt-color-dot.color-green { background: #bbf7d0; }
.nt-color-dot.color-blue { background: #bae6fd; }
.nt-color-dot.color-purple { background: #e9d5ff; }

