.nt-card.color-pink {
  background: var(--nt-note-pink-bg);
  border-color: var(--nt-note-pink-edge);
}
.nt-card.color-green {
  background: var(--nt-note-green-bg);
  border-color: var(--nt-note-green-edge);
}
.nt-card.color-blue {
  background: var(--nt-note-blue-bg);
  border-color: var(--nt-note-blue-edge);
}
.nt-card.color-purple {
  background: var(--nt-note-purple-bg);
  border-color: var(--nt-note-purple-edge);
}

