.nt-card-pin-badge {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: light-dark(#ffffff88, #00000033);
  color: var(--nt-primary);
  flex-shrink: 0;
}
.nt-card-body {
  flex: 1;
  font-size: 13px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--nt-text);
