.nt-icon-btn {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: light-dark(#ffffff88, #00000033);
  color: var(--nt-muted);
  transition: all 0.15s ease;
