  padding: 4px 6px;
  font-size: 14px;
  font-weight: 600;
  border: 1px solid var(--nt-edge);
  border-radius: 4px;
  background: light-dark(#ffffffaa, #00000044);
  color: var(--nt-text);
}
.nt-card-edit-content {
  width: 100%;
  padding: 6px;
  font-size: 13px;
  line-height: 1.5;
  border: 1px solid var(--nt-edge);
  border-radius: 4px;
  background: light-dark(#ffffffaa, #00000044);
  color: var(--nt-text);
  resize: vertical;
  min-height: 70px;
}
.nt-card-edit-actions {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  margin-top: 6px;
}
.nt-btn-save {
  padding: 3px 10px;
  font-size: 12px;
  border: 0;
  border-radius: 4px;
  background: var(--nt-primary);
  color: #fff;
