/* 空状态 */
.nt-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
  color: var(--nt-muted);
  border: 1px dashed var(--nt-edge);
  border-radius: 12px;
  background: var(--nt-panel);
}
.nt-empty-icon {
  margin-bottom: 12px;
  opacity: 0.5;
}
.nt-empty-text {
  font-size: 13px;
}

/* 错误提示条 */
.nt-error-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  margin-bottom: 16px;
  border-radius: 8px;
  font-size: 13px;
  background: light-dark(#fef2f2, #7f1d1d33);
  color: light-dark(#991b1b, #f87171);
  border: 1px solid light-dark(#fecaca, #7f1d1d);
}

